result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "wsframe.py", "content": """"Minimal WebSocket frame codec (RFC 6455 section 5.2) using only the stdlib.

Public API:
    encode_frame(payload, opcode, fin=True, mask_key=None) -> bytes
    decode_frame(buf) -> (fin, opcode, payload, consumed)

Exceptions:
    WsError          -- protocol violation (bad length encoding, bad RSV, ...)
    IncompleteFrame  -- buffer holds a truncated frame (subclass of WsError)
"""

from __future__ import annotations


class WsError(Exception):
    """A WebSocket framing protocol violation."""


class IncompleteFrame(WsError):
    """The buffer does not yet contain a full frame."""


def _apply_mask(payload: bytes, key: bytes) -> bytes:
    """XOR payload with the repeating 4-byte mask key."""
    return bytes(b ^ key[i % 4] for i, b in enumerate(payload))


def encode_frame(
    payload: bytes,
    opcode: int,
    fin: bool = True,
    mask_key: "bytes | None" = None,
) -> bytes:
    """Encode one WebSocket frame. mask_key must be None or exactly 4 bytes."""
    payload = bytes(payload)
    if mask_key is not None and len(mask_key) != 4:
        raise WsError("mask key must be exactly 4 bytes")
    if opcode >= 0x8:  # control frames
        if len(payload) > 125:
            raise WsError("control frame payload must be < 126 bytes")
        if not fin:
            raise WsError("control frames must not be fragmented")

    first = (0x80 if fin else 0x00) | (opcode & 0x0F)
    masked_flag = 0x80 if mask_key is not None else 0x00

    header = bytearray([first])
    n = len(payload)
    if n < 126:
        header.append(masked_flag | n)
    elif n <= 0xFFFF:
        header.append(masked_flag | 126)
        header += n.to_bytes(2, "big")
    else:
        header.append(masked_flag | 127)
        header += n.to_bytes(8, "big")

    if mask_key is not None:
        return bytes(header) + mask_key + _apply_mask(payload, mask_key)
    return bytes(header) + payload


def decode_frame(buf: bytes) -> tuple:
    """Decode one frame from buf.

    Returns (fin, opcode, payload, consumed).
    Raises IncompleteFrame if buf is a prefix of a valid frame,
    WsError on any protocol violation.
    """
    buf = bytes(buf)

    if len(buf) < 2:
        raise IncompleteFrame("need at least 2 bytes for the base header")
    b0, b1 = buf[0], buf[1]

    fin = bool(b0 & 0x80)
    if b0 & 0x70:
        raise WsError("reserved RSV bits must be zero")
    opcode = b0 & 0x0F

    masked = bool(b1 & 0x80)
    length = b1 & 0x7F
    offset = 2

    if length == 126:
        if len(buf) < offset + 2:
            raise IncompleteFrame("truncated 16-bit extended length")
        length = int.from_bytes(buf[offset : offset + 2], "big")
        offset += 2
        if length < 126:
            raise WsError("non-minimal length encoding: 16-bit form used for %d bytes" % length)
    elif length == 127:
        if len(buf) < offset + 8:
            raise IncompleteFrame("truncated 64-bit extended length")
        ext = buf[offset : offset + 8]
        if ext[0] & 0x80:
            raise WsError("MSB of 64-bit length must be zero")
        length = int.from_bytes(ext, "big")
        offset += 8
        if length <= 0xFFFF:
            raise WsError("non-minimal length encoding: 64-bit form used for %d bytes" % length)

    if opcode >= 0x8:
        if length > 125:
            raise WsError("control frame payload must be < 126 bytes")
        if not fin:
            raise WsError("control frames must not be fragmented")

    mask_key = b""
    if masked:
        if len(buf) < offset + 4:
            raise IncompleteFrame("truncated 4-byte mask key")
        mask_key = buf[offset : offset + 4]
        offset += 4

    end = offset + length
    if len(buf) < end:
        raise IncompleteFrame("payload incomplete (%d of %d bytes)" % (len(buf) - offset, length))

    payload = buf[offset:end]
    if masked:
        payload = _apply_mask(payload, mask_key)
    return fin, opcode, bytes(payload), end
"})
